    if (head) { if (!th) { th = document.createElement("thead"); el.insertBefore(th, tb); } th.innerHTML = "<tr>" + head.map(h => cell(h, "th")).join("") + "</tr>"; }
    tb.innerHTML = rows.map((r, i) => `<tr${rowAttr ? rowAttr(i) : ""}>` + r.map(c => cell(c, "td")).join("") + "</tr>").join("");
